    "G01S1/54": {
      "code": "G01S1/54",
      "level": 11,
      "parent": "G01S1/44",
      "ja": "受信機において，ビーム搬送波のパルス形包絡線信号を作り出し，かつそのタイミングがビーコンに対する受信機の方向とビーコンに対する基準方向との間の角度に依存する狭ビーム方式；受信機において，ビーム搬送波のパルス形包絡線信号を作り出し，かつそのタイミングが，ビーコンに対する受信機の方向とビーコンに対する基準方向との間の角度に依存している，狭い範囲を定める重複広ビーム方式",
      "en": "Narrow-beam systems producing at a receiver a pulse-type envelope signal of the carrier wave of the beam, the timing of which is dependent upon the angle between the direction of the receiver from the beacon and a reference direction from the beacon; Overlapping broad beam systems defining a narrow zone and producing at a receiver a pulse-type envelope signal of the carrier wave of the beam, the timing of which is dependent upon the angle between the direction of the receiver from the beacon and a reference direction from the beacon",
      "count": 71,
      "ipcCode": "G01S1/54",
      "coreCode": "G01S1/54",
      "note": "",
      "sourceFile": "cpc_G01S.txt",
      "kind": "cpc"
    },
