    "G01S15/00": {
      "code": "G01S15/00",
      "level": 7,
      "parent": null,
      "ja": "音波の反射または再放射を使用する方式，例．ソーナ方式注．グループＧ０１Ｓ１３／００に続く注は，このグループにも適用する",
      "en": "Systems using the reflection or reradiation of acoustic waves, e.g. sonar systems<br><br><u>NOTE</u><br><br> This group covers : <br>systems for detecting the presence of an object, e.g. by  reflection or reradiation from the object itself, or from  a transponder associated with the object, for determining  the distance or relative velocity of an object, for  providing a co-ordinated display of the distance and  direction of an object or for obtaining an image thereof; <br>systems arranged for mounting on a moving craft or vehicle  and using the reflection of waves from an extended surface  external to the craft, e.g. the surface of the earth, to  determine the velocity and direction of motion of the craft  relative to the surface. <br> This group does not cover : <br>systems for determining the direction of an object by means  not employing reflection or reradiation, which are covered  by groups G01S1/00 or G01S3/00; <br>systems for determining distance or velocity of an object  by means not employing reflection or reradiation, which are  covered by group G01S11/00. ",
      "count": 288,
      "ipcCode": "G01S15/00",
      "coreCode": "G01S15/00",
      "note": "",
      "sourceFile": "cpc_G01S.txt",
      "kind": "cpc"
    },
